sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    // var mfunction = g_form.getValue('u_mincident.u_rule_s_to_add_change_remove');
    var mdtable = document.getElementById("md_table_2");
	console.log("Cs: " + mdtable);
	// Get data rows from the table to insert into pop up md-table_2 after header row
	// var rowsToMove = [];
	// if (mdtable) {
	// 	console.log(mdtable.rows.length);
	// 	for (i = 0; i < mdtable.rows.length; i++) {
	// 		if (i=0) continue;
	// 		rowsToMove[i] = mdtable.rows[i];
	// 		console.log(rowsToMove[i]);
	// 	}
	// }

    showCustomModal(myCallback, mdtable);
}

function myCallback(result) {
    g_form.setValue('u_rule_data', result);
	var selects = document.getElementById('u_mincident.u_rule_s_to_add_change_remove');
	selects.selectedIndex = 0;
}

function showCustomModal(xCallback, xmdtable) {
	console.log(xmdtable);
    var modal = new GlideModal('custom_modal');
    modal.setTitle('Enter firewall rules');
    modal.setWidth(900);

    // Define the HTML content with an input field
    var mdHTML = '<div id="mdfwdiv" style="width:800px">' +
        '<table id="md_table_1" style="width:800px;margin-bottom:25px;">' +
        '<tr>' +
        '<td>' +
        '<input id="addRowBtn" type="text" value="New" style="width:120px;border:1px solid black;padding:4px;text-align: left;' +
        ' background-color:#2da44c;color:white;onclick="addRow(this);"></td>' +
        '</tr>' +
        '<tr style="background-color: #f3f3f3">' +
        '<th style="width:95px;border:1px solid black;padding:4px;text-align:left;">Source zone</th>' +
        '<th style="width:80px;border:1px solid black;padding:4px;text-align:left;">Select</th>' +
        '<th style="width:120px;border:1px solid black;padding:4px;text-align:left;">Src. IP/Netmask/FQDN</th>' +
        '<th style="width:95px;border:1px solid black;padding:4px;text-align:left;">Destination zone</th>' +
        '<th style="width:80px;border:1px solid black;padding:4px;text-align:left;">Select</th>' +
        '<th style="width:120px;border:1px solid black;padding:4px;text-align:left;">Dst. IP/Netmask/FQDN</th>' +
        '</tr>' +
        '<tr>' +
        '<td style="width:95px;border:1px solid black;padding:4px;text-align:left;">' +
		'<input type="text" placeholder="Source-Zone-A" style="border:0px solid white;"></td>' +
        '<td style="width:81px;border:1px solid black;padding:4px;text-align:left;">' +
        '<select id="srcopt" style="border:0px solid white;">' +
        '<option value="IP">IP</option>' +
        '<option value="Netmask">Netmask</option>' +
        '<option value="FQDN">FQDN</option>' +
        '</select></td>' +
        '<td style="width:129px;border:1px solid black;padding:4px;text-align:left;">' +
		'<input type="text" placeholder="192.168.1.2" style="border:0px solid white;"></td>' +
        '<td style="width:95px;border:1px solid black;padding:4px;text-align:left;">' +
		'<input type="text" placeholder="Destination-Zone-A" style="border:0px solid white;"></td>' +
        '<td style="width:81px;border:1px solid black;padding:4px;text-align:left;">' +
        '<select id="srcopt" style="border:0px solid white;">' +
        '<option value="IP">IP</option>' +
        '<option value="Netmask">Netmask</option>' +
        '<option value="FQDN">FQDN</option>' +
        '</select></td>' +
        '<td style="width:129px;border:1px solid black;padding:4px;text-align:left;">' +
		'<input type="text" placeholder="192.168.1.3" style="border:0px solid white;"></td>' +
        '</tr>' +
        '</table>' +
        '<input id="removeRowsWithXBtn" type="text" value="Delete selected" onclick="removeRowsWithX();"' +
        ' style="width:120px;border:1px solid black;padding:4px;background-color:#FF0000;color: white;">' +
        '<table id="md_table_2" style="width:830px;margin-bottom:25px;">' +
        '<tr style="background-color:#f3f3f3">' +
        '<th style="width:30px;border:1px solid black;padding:4px;text-align:left;">Sel</th>' +
        '<th style="width:165px;border:1px solid black;padding:4px;text-align:left;">Source zone</th>' +
        '<th style="width:75px;border:1px solid black;padding:4px;text-align:left;">Selected</th>' +
        '<th style="width:165px;border:1px solid black;padding:4px;text-align:left;">Src. IP/Netmask/FQDN</th>' +
        '<th style="width:165px;border:1px solid black;padding:4px;text-align:left;">Destination zone</th>' +
        '<th style="width:75px;border:1px solid black;padding:4px;text-align:left;">Selected</th>' +
        '<th style="width:165px;border:1px solid black;padding:4px;text-align:left;">Dst. IP/Netmask/FQDN</th>' +
        '</tr>' +
        '</table>' +
		'<button id="submitBtn">Submit</button></div>';
	// Get table to be extended
	var tableToExtend = document.getElementById('md_table_2');
	var numberOfCells = 7; // Number of cells in the table
	console.log(tableToExtend);
	console.log(xmdtable);
	// Add passed rows to md_table_2
	// console.log("Row 1: ");
	// console.log(xrowsToMove[0]);
	// console.log("Row 2: ");
	// console.log(xrowsToMove[1]);
	// if (xrowsToMove) {
	// 	for (i = 0; i < xrowsToMove.length; i++) {
	// 		console.log(xrowsToMove[i]);
	// 		var newRow = tableToExtend.insertRow(-1); // Add a new empty row to the end of the table
	// 		// Add cells to the row
	// 		for (j = 0; j < numberOfCells; j++) {
	// 			var newCell = newRow.insertCell(j);
	// 			console.log(newCell);
	// 			newCell = xrowsToMove[i].cells[j];
	// 			console.log(newCell);
	// 		}
	// 	}

	// }


    modal.renderWithContent(mdHTML);

    // Add a click listener to the Submit button to send data back
    setTimeout(function() {
        console.log('in setTimeout');
        var submitButton = document.getElementById('submitBtn');
        var table1 = document.getElementById('md_table_1');
        var table2 = document.getElementById('md_table_2');
        if (submitButton) {
            submitButton.onclick = function() {
                console.log('sumitted');
                var userInput = table2.outerHTML;
                xCallback(userInput);
                modal.close();
            };
        }
        var addRowButton = document.getElementById("addRowBtn");
        if (addRowButton) {
            addRowButton.onclick = function() {
                // Get the table element
                console.log('in addRow');
                // Get the first row
                var firstRow = table1.rows[2]; // Assuming the first row is at index 2
                // Get all cells from the first row
                var table1_cells = firstRow.cells;
                // Create a new row
                var newRow = table2.insertRow(-1); // Insert at the end of the table
                // Insert new cells in the row
                for (let i = 0; i < 9; i++) {
                    const newCell = newRow.insertCell(i);
                    if (i === 0) {
                        // Add a checkbox to the first cell
                        newCell.innerHTML = '<input type="checkbox">';
                        newCell.style.border = '1px solid black';
                        newCell.style.padding = '4px';
                        newCell.style.textAlign = 'left';
                    } else {
                        // Check if the cell contains an input element
                        if (table1_cells[i - 1].querySelector('input')) {
                            const inputElement = table1_cells[i - 1].querySelector('input');
                            newCell.innerHTML = inputElement.value;
                            newCell.style.width = 'width: 100px;';
                            newCell.style.border = '1px solid black';
                            newCell.style.padding = '4px';
                            newCell.style.textAlign = 'left';
                        } else if (table1_cells[i - 1].querySelector('select')) {
                            const selectElement = table1_cells[i - 1].querySelector('select');
                            newCell.innerHTML = selectElement.value;
                            newCell.style.width = 'width: 70px;';
                            newCell.style.border = '1px solid black';
                            newCell.style.padding = '4px';
                            newCell.style.textAlign = 'left';
                        } else {
                            newCell.innerHTML = table1_cells[i - 1].innerHTML;
                            newCell.style.width = 'width: 100px;';
                            newCell.style.border = '1px solid black';
                            newCell.style.padding = '4px';
                            newCell.style.textAlign = 'left';
                        }
                    }

                }
            };
        }
        var removeRowsWithXButton = document.getElementById("removeRowsWithXBtn");
        if (removeRowsWithXButton) {
            removeRowsWithXButton.onclick = function() {
                console.log('in removeRowsWithX');
                // Get the table
                var table = document.getElementById('md_table_2');
                console.log(table);
                // Loop through the rows in reverse order (to avoid index shifting when removing rows)
                for (let i = table.rows.length - 1; i > 0; i--) {
                    var firstCell = table.rows[i].cells[0];
                    var checkbox = firstCell.querySelector('input[type="checkbox"]');
                    if (checkbox && checkbox.checked) {
                        table.deleteRow(i); // Remove the row if the checkbox is checked
                    }
                }
            }
        }


    }, 500);

}
